import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchCurrencyPredictions = async () => {
        try {
            const response = await fetch('http://localhost:8000/currency-prophet-predictions');
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const result = await response.json();
            const lastValues = result.values.map((value, index) => ({
                name: result.dates[index],
                value: value
            }));
            const predictedValues = result.predictions.map((value, index) => ({
                name: `Predicción ${index + 1}`,
                value: value
            }));

            // Concatenar datos reales y predicciones
            setData([...lastValues, ...predictedValues]);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching currency predictions:', error.message);
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCurrencyPredictions();
        const intervalId = setInterval(fetchCurrencyPredictions, 10000); // Actualiza cada 10 segundos

        return () => clearInterval(intervalId); // Limpia el intervalo al desmontar
    }, []);

    if (loading) {
        return <div>Cargando...</div>; // O un spinner/loading icon
    }

    return (
        <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Line type="monotone" dataKey="value" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
